template <typename T, Command::EnableIfSame<T>*>
bool Command::Equals(const T& other_struct) const {
  if (!mojo::Equals(this->name, other_struct.name))
    return false;
  if (!mojo::Equals(this->id, other_struct.id))
    return false;
  if (!mojo::Equals(this->modified, other_struct.modified))
    return false;
  if (!mojo::Equals(this->accelerators, other_struct.accelerators))
    return false;
  return true;
}

template <typename T, Command::EnableIfSame<T>*>
bool operator<(const T& lhs, const T& rhs) {
  if (lhs.name < rhs.name)
    return true;
  if (rhs.name < lhs.name)
    return false;
  if (lhs.id < rhs.id)
    return true;
  if (rhs.id < lhs.id)
    return false;
  if (lhs.modified < rhs.modified)
    return true;
  if (rhs.modified < lhs.modified)
    return false;
  if (lhs.accelerators < rhs.accelerators)
    return true;
  if (rhs.accelerators < lhs.accelerators)
    return false;
  return false;
}
